    "notifications.inApp.v1",
    "notifications.owner.v1",
    "automations.conditions.v1"
  ],
  "collections": [
    {
      "id": "tasks",
      "label": "Tasks",
      "fields": [
        {
          "id": "title",
          "label": "Task",
          "type": "text",
          "required": true
        },
        {
          "id": "status",
          "label": "Status",
          "type": "choice",
          "required": true,
          "choices": ["Open", "Done"]
        },
        {
          "id": "priority",
          "label": "Priority",
          "type": "choice",
          "required": false,
          "choices": ["Low", "Normal", "High"]
        },
        {
          "id": "notes",
          "label": "Notes",
          "type": "text",
          "required": false
        },
        {
          "id": "dueAt",
