          "label": "Remind me",
          "type": "timestamp",
          "required": false
        }
      ],
      "behaviors": [
        {
          "id": "taskProgress",
          "type": "workflow.v1",
          "fieldId": "status",
          "transitions": {
            "Open": ["Done"],
            "Done": ["Open"]
          }
        }
      ]
    }
  ],
  "views": [
    {
      "id": "todaySummary",
      "type": "summary",
      "collectionId": "tasks",
      "label": "Today at a glance",
