        "fieldId": "dueAt",
        "period": "today"
      }
    },
    {
      "id": "todayTasks",
      "type": "list",
      "collectionId": "tasks",
      "label": "Scheduled today",
      "titleFieldId": "title",
      "actionIds": ["addTask", "editTask", "moveTask"],
      "presentation": "compact",
      "fieldIds": ["status", "priority", "dueAt"],
      "query": {
        "sort": [
          {
            "fieldId": "dueAt",
            "descending": false
          }
        ],
        "limit": 25
      },
      "dateFilter": {
        "fieldId": "dueAt",
        "period": "today"
      },
      "detailPageId": "taskDetailPage",
      "formPageId": "taskEditorPage"
    },
    {
      "id": "overdueTasks",
      "type": "list",
      "collectionId": "tasks",
      "label": "Overdue",
      "titleFieldId": "title",
      "actionIds": ["editTask", "moveTask"],
      "presentation": "compact",
      "fieldIds": ["priority", "dueAt"],
      "query": {
        "filters": [
          {
            "fieldId": "status",
            "operator": "eq",
            "value": "Open"
          }
        ],
        "sort": [
          {
            "fieldId": "dueAt",
            "descending": false
          }
        ],
        "limit": 25
      },
      "dateFilter": {
        "fieldId": "dueAt",
        "period": "overdue"
      },
      "detailPageId": "taskDetailPage",
      "formPageId": "taskEditorPage"
    },
    {
      "id": "allTasks",
      "type": "list",
      "collectionId": "tasks",
      "label": "All tasks",
      "titleFieldId": "title",
      "actionIds": ["addTask", "editTask", "moveTask"],
      "presentation": "cards",
      "fieldIds": ["status", "priority", "dueAt"],
      "filterFieldIds": ["status", "priority"],
      "query": {
        "sort": [
          {
            "fieldId": "dueAt",
            "descending": false
          }
        ],
        "limit": 25
      },
      "detailPageId": "taskDetailPage",
      "formPageId": "taskEditorPage"
    },
    {
      "id": "todayProgress",
      "type": "summary",
      "collectionId": "tasks",
      "label": "Today's scheduled tasks",
      "groupByFieldId": "status",
      "actionIds": [],
      "dateFilter": {
        "fieldId": "dueAt",
        "period": "today"
      }
    },
    {
      "id": "allProgress",
      "type": "summary",
      "collectionId": "tasks",
      "label": "All tasks",
      "groupByFieldId": "status",
      "actionIds": []
    },
    {
      "id": "taskDetails",
      "type": "details",
      "collectionId": "tasks",
      "label": "Task details",
      "titleFieldId": "title",
      "actionIds": ["editTask", "moveTask"],
      "fieldIds": ["status", "priority", "notes", "dueAt", "reminderAt"],
      "formPageId": "taskEditorPage"
    },
    {
      "id": "taskEditor",
      "type": "form",
      "collectionId": "tasks",
      "label": "Task editor",
      "titleFieldId": "title",
      "actionIds": ["addTask", "editTask"],
      "fieldIds": ["title", "priority", "notes", "dueAt", "reminderAt"]
    }
  ],
  "actions": [
    {
      "id": "addTask",
      "label": "Add task",
      "capability": "records.create.v1",
      "collectionId": "tasks"
    },
    {
      "id": "editTask",
      "label": "Edit task",
      "capability": "records.patch.v1",
      "collectionId": "tasks"
    },
    {
      "id": "moveTask",
      "label": "Complete or reopen",
      "capability": "workflow.transition.v1",
      "collectionId": "tasks",
      "behaviorId": "taskProgress"
    }
  ],
  "policyPresetRequest": "personalTracker.v1",
  "automationRequests": [
    {
      "id": "taskReminder",
      "trigger": {
        "type": "beforeTimestamp",
        "collectionId": "tasks",
        "fieldId": "reminderAt",
        "offsetSeconds": 0
      },
      "effect": {
        "type": "notifyOwner",
        "channel": "inApp"
      },
      "condition": {
        "fieldId": "status",
        "value": "Open"
      }
    }
  ],
  "navigation": {
    "entryPageId": "tasksPage",
